import { useState } from 'react'
import { useParams } from 'react-router-dom'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { Target, Plus, ChevronRight, X } from 'lucide-react'
import { goalsService } from '@/integrations/supabase/goals'

export function GoalsPage() {
  const { projectId } = useParams()
  const qc = useQueryClient()
  const [showNew, setShowNew] = useState(false)
  const [title, setTitle] = useState('')

  const { data: goals = [], isLoading } = useQuery({
    queryKey: ['goals', projectId],
    queryFn: () => goalsService.listGoals(projectId),
  })

  const createMut = useMutation({
    mutationFn: () => goalsService.createGoal({ title, projectId }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['goals', projectId] })
      setShowNew(false)
      setTitle('')
      toast.success('Goal created')
    },
    onError: (e: Error) => toast.error(e.message),
  })

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-3xl mx-auto">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h2 className="font-semibold">Goals</h2>
            <p className="text-sm text-muted-foreground">Track high-level project goals</p>
          </div>
          <button onClick={() => setShowNew(true)} className="flex items-center gap-1.5 text-sm bg-accent text-accent-foreground px-3 py-1.5 rounded-lg hover:opacity-90">
            <Plus size={14} /> New goal
          </button>
        </div>

        {isLoading ? (
          <p className="text-sm text-muted-foreground">Loading…</p>
        ) : goals.length === 0 ? (
          <div className="rounded-xl border border-dashed border-border p-10 text-center">
            <p className="text-sm text-muted-foreground">No goals yet</p>
          </div>
        ) : (
          <div className="flex flex-col gap-3">
            {goals.map((goal) => (
              <div key={goal.id} className="bg-surface rounded-xl border border-border p-5">
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-2">
                    <Target size={16} className="text-accent" />
                    <span className="font-medium text-sm">{goal.title}</span>
                  </div>
                  <button className="text-muted-foreground hover:text-foreground"><ChevronRight size={16} /></button>
                </div>
                <div className="flex items-center gap-3">
                  <div className="flex-1 h-2 bg-muted rounded-full overflow-hidden">
                    <div className="h-full bg-accent rounded-full transition-all" style={{ width: `${goal.progress ?? 0}%` }} />
                  </div>
                  <span className="text-xs text-muted-foreground w-10 text-right">{goal.progress ?? 0}%</span>
                </div>
                <p className="text-xs text-muted-foreground mt-2">{goal.linkedObjectives ?? 0} linked objective{(goal.linkedObjectives ?? 0) !== 1 ? 's' : ''}</p>
              </div>
            ))}
          </div>
        )}

        {showNew && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-surface rounded-2xl border border-border w-full max-w-md shadow-xl">
              <div className="flex items-center justify-between p-5 border-b border-border">
                <h3 className="font-semibold">New goal</h3>
                <button onClick={() => setShowNew(false)} className="p-1.5 rounded-lg hover:bg-muted"><X size={16} /></button>
              </div>
              <div className="p-5 flex flex-col gap-4">
                <input value={title} onChange={(e) => setTitle(e.target.value)} autoFocus placeholder="Goal title…" className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" />
                <div className="flex justify-end gap-2">
                  <button onClick={() => setShowNew(false)} className="px-4 py-2 text-sm text-muted-foreground hover:text-foreground">Cancel</button>
                  <button onClick={() => createMut.mutate()} disabled={!title || createMut.isPending} className="px-4 py-2 text-sm bg-accent text-accent-foreground rounded-lg hover:opacity-90 disabled:opacity-50">
                    {createMut.isPending ? 'Creating…' : 'Create'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}
